CREATE FUNCTION public.activity_workspace(_month date,_client uuid DEFAULT NULL,_code text DEFAULT NULL,_mine boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN PERFORM activity_require_ready(); SELECT jsonb_build_object('pipelines',coalesce((SELECT jsonb_agg(jsonb_build_object('id',cp.id,'client_id',cp.client_id,'hotel',c.hotel_name,'pipeline_id',pl.id,'code',pl.code,'name',pl.name,'can_edit',activity_can_head(cp.id),'people',CASE WHEN has_role(auth.uid(),'client') THEN '[]'::jsonb ELSE coalesce((SELECT jsonb_agg(jsonb_build_object('id',a.user_id,'name',pr.full_name,'role',a.role) ORDER BY CASE WHEN a.role='head' THEN 0 ELSE 1 END,pr.full_name) FROM client_staff_assignments a JOIN profiles pr ON pr.id=a.user_id AND pr.status='active' WHERE a.client_id=cp.client_id AND a.pipeline_id=cp.pipeline_id AND NOT a.excluded),'[]') END)) FROM client_pipelines cp JOIN pipelines pl ON pl.id=cp.pipeline_id JOIN clients c ON c.id=cp.client_id WHERE cp.status<>'ended' AND pl.code<>'business_development' AND activity_can_read(cp.id) AND (_client IS NULL OR cp.client_id=_client) AND (_code IS NULL OR pl.code=_code) AND (NOT c.is_demo OR _client=c.id)),'[]'),
 'plans',coalesce((SELECT jsonb_agg(jsonb_build_object('id',p.id,'cp',cp.id,'hotel',c.hotel_name,'pipeline',pl.name,'month',p.month,'version',p.version,'status',p.status,'comment',p.comment,'can_edit',activity_can_head(cp.id),'can_approve',has_role(auth.uid(),'client') AND p.status='pending','items',coalesce((SELECT jsonb_agg(to_jsonb(i) ORDER BY i.publish_on,i.name) FROM activity_items i WHERE i.plan_id=p.id),'[]'),'planned',coalesce((SELECT sum(quantity) FROM activity_items WHERE plan_id=p.id),0),'done',coalesce((SELECT sum(i.quantity) FROM activity_items i WHERE i.plan_id=p.id AND EXISTS(SELECT 1 FROM recurring_tasks t WHERE t.family_id=p.family_id AND t.occurrence_key=i.occurrence_key AND t.stage='publish' AND t.status='done')),0),'on_time', (SELECT round(100.0*count(*) FILTER(WHERE t.status='done' AND (t.done_at AT TIME ZONE 'Asia/Kolkata')::date<=t.original_due_date)/nullif(count(*),0),2) FROM recurring_tasks t WHERE t.family_id=p.family_id AND (t.plan_id=p.id OR t.status='done') AND t.status<>'superseded'))) FROM activity_plans p JOIN client_pipelines cp ON cp.id=p.client_pipeline_id JOIN pipelines pl ON pl.id=cp.pipeline_id JOIN clients c ON c.id=cp.client_id WHERE p.month=date_trunc('month',_month)::date AND activity_can_read(cp.id) AND (NOT has_role(auth.uid(),'client') OR p.status<>'draft') AND (_client IS NULL OR cp.client_id=_client) AND (_code IS NULL OR pl.code=_code) AND (NOT c.is_demo OR _client=c.id)),'[]'),
 'tasks',CASE WHEN has_role(auth.uid(),'client') THEN '[]'::jsonb ELSE coalesce((SELECT jsonb_agg(jsonb_build_object('id',t.id,'name',i.name,'quantity',i.quantity,'stage',t.stage,'due_date',t.due_date,'original_due_date',t.original_due_date,'status',CASE WHEN t.status IN('not_started','in_progress') AND (p.month+interval '1 month')::date<=(now() AT TIME ZONE 'Asia/Kolkata')::date AND t.due_date<(now() AT TIME ZONE 'Asia/Kolkata')::date AND NOT client_on_hold(cp.client_id) THEN 'missed_review' ELSE t.status END,'hotel',c.hotel_name,'pipeline',pl.name,'owner',pr.full_name,'backup',br.full_name,'owner_id',t.owner_id,'backup_id',t.backup_id,'can_edit',NOT client_on_hold(cp.client_id) AND (activity_can_head(cp.id) OR auth.uid() IN(t.owner_id,t.backup_id)),'can_review',activity_can_head(cp.id),'on_hold',client_on_hold(cp.client_id),'review_reason',t.review_reason) ORDER BY t.due_date) FROM recurring_tasks t JOIN activity_items i ON i.id=t.item_id JOIN activity_plans p ON p.id=t.plan_id JOIN client_pipelines cp ON cp.id=p.client_pipeline_id JOIN pipelines pl ON pl.id=cp.pipeline_id JOIN clients c ON c.id=cp.client_id LEFT JOIN profiles pr ON pr.id=t.owner_id LEFT JOIN profiles br ON br.id=t.backup_id WHERE activity_can_read(cp.id) AND (_client IS NULL OR cp.client_id=_client) AND (_code IS NULL OR pl.code=_code) AND ((_mine AND auth.uid() IN(t.owner_id,t.backup_id)) OR (NOT _mine AND p.month=date_trunc('month',_month)::date)) AND (NOT c.is_demo OR _client=c.id)),'[]') END,'types',coalesce((SELECT jsonb_agg(to_jsonb(a)) FROM activity_types a WHERE a.active),'[]')) INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.activity_workspace(date,uuid,text,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.activity_workspace(date,uuid,text,boolean) TO authenticated;
CREATE FUNCTION public.activity_person_summary(_month date) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM activity_require_ready(); IF NOT(is_staff(auth.uid()) OR has_role(auth.uid(),'hr')) THEN RAISE EXCEPTION 'Staff only'; END IF; RETURN coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT pr.id,pr.full_name,count(*) due,count(*) FILTER(WHERE t.status='done') done,count(*) FILTER(WHERE t.stage='publish') planned_items,count(*) FILTER(WHERE t.stage='publish' AND t.status='done') completed_items,round(100.0*count(*) FILTER(WHERE t.status='done' AND (t.done_at AT TIME ZONE 'Asia/Kolkata')::date<=t.original_due_date)/nullif(count(*),0),2) on_time FROM recurring_tasks t JOIN profiles pr ON pr.id=t.owner_id JOIN activity_plans p ON p.id=t.plan_id JOIN client_pipelines cp ON cp.id=p.client_pipeline_id JOIN clients c ON c.id=cp.client_id WHERE t.original_due_date>=date_trunc('month',_month)::date AND t.original_due_date<(date_trunc('month',_month)+interval '1 month')::date AND t.status<>'superseded' AND NOT c.is_demo AND NOT c.is_test AND NOT client_on_hold(cp.client_id) AND (is_manager(auth.uid()) OR has_role(auth.uid(),'hr') OR t.owner_id=auth.uid()) GROUP BY pr.id,pr.full_name) x),'[]'); END $$; REVOKE ALL ON FUNCTION public.activity_person_summary(date) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.activity_person_summary(date) TO authenticated;
DO $$ DECLARE f text; BEGIN SELECT pg_get_functiondef('public.team_scorecard(date)'::regprocedure) INTO f; f:=replace(f,'FROM client_tasks t JOIN client_launches lh ON lh.id = t.launch_id AND lh.status <> ''on_hold''','FROM (SELECT assignee_id,due_date,status,done_at,launch_id FROM client_tasks UNION ALL SELECT rt.owner_id,rt.original_due_date,CASE WHEN rt.status=''superseded'' THEN ''not_applicable'' ELSE rt.status END,rt.done_at,(SELECT l.id FROM client_launches l JOIN activity_plans ap ON ap.id=rt.plan_id JOIN client_pipelines cp ON cp.id=ap.client_pipeline_id WHERE l.client_id=cp.client_id AND l.status IN(''active'',''live'',''offboarding'') ORDER BY l.created_at DESC LIMIT 1) FROM recurring_tasks rt) t JOIN client_launches lh ON lh.id = t.launch_id AND lh.status <> ''on_hold'''); EXECUTE f; SELECT pg_get_functiondef('public._department_actual(uuid,date,text)'::regprocedure) INTO f; f:=replace(f,'FROM client_tasks t JOIN clients c ON c.id=t.client_id JOIN client_launches l ON l.id=t.launch_id','FROM (SELECT assignee_id,due_date,status,done_at,client_id,launch_id FROM client_tasks UNION ALL SELECT rt.owner_id,rt.original_due_date,CASE WHEN rt.status=''superseded'' THEN ''not_applicable'' ELSE rt.status END,rt.done_at,cp.client_id,(SELECT l.id FROM client_launches l WHERE l.client_id=cp.client_id AND l.status IN(''active'',''live'',''offboarding'') ORDER BY l.created_at DESC LIMIT 1) FROM recurring_tasks rt JOIN activity_plans ap ON ap.id=rt.plan_id JOIN client_pipelines cp ON cp.id=ap.client_pipeline_id) t JOIN clients c ON c.id=t.client_id JOIN client_launches l ON l.id=t.launch_id'); EXECUTE f; END $$;